		maintenanceTerminalCustody.set(source, sourceFacts);
		try {
			const observer = Reflect.get(globalThis, "__warmProofEvent");
			if (typeof observer === "function") observer({kind: "ordinary-readiness-source-upgrade", outcome: "captured",
				epoch: currentTrust.currentEpoch, chargedBytes: proof.accounting.chargedBytes, knownCarriers: knownMaterial.length});
		} catch { /* The DATA token is already enrolled; observations grant no authority. */ }
