		if (keys.length !== methods.length || !methods.every(key =>
			fields[key] !== undefined && "value" in fields[key]! && typeof fields[key]!.value === "function")) return;
		const value = projection.quoteWithoutApplicationCandidate!();
		if (value === undefined || Object.getPrototypeOf(value) !== Object.prototype || Reflect.ownKeys(value).length !== 3 ||
			![value.byteLength, value.items, value.maxDepth].every(Number.isSafeInteger) || value.byteLength < 1 || value.items < 1 ||
			value.maxDepth < 0 || value.byteLength > preparation.current.blueprint.maxApplicationStateBytes ||
			value.items > preparation.current.blueprint.maxItems || value.maxDepth > preparation.current.blueprint.maxDepth ||
			compareBytes(closedRetirementBytes(input), bytes) !== 0) return;
